member.example:
Usage:
            
            Calculator calc = new Calculator();
            // arithmetics
            double result = calc.Calculate("(2 + 1) * (1 + 2)");
            // calling a function
            double result = calc.Calculate("sqrt(4)");
            // trigonometry
            double result = calc.Calculate("cos(pi * 45 / 180.0)");
            // unit conversion
            double result = calc.Calculate("12 [in->ft]");
            // variables
            double result = calc.Calculate("Answer * 10");
